package main

import "fmt"

type User struct {
	ID   int
	Name string
}

// Escapes to Heap: Returns pointer to local struct outside function frame.
func NewUserHeap(name string) *User {
	u := User{ID: 1, Name: name} // ESCAPES TO HEAP
	return &u
}

// Stays on Stack: Struct is returned by value (copied across stack frame).
func NewUserStack(name string) User {
	u := User{ID: 2, Name: name} // STAYS ON STACK
	return u
}

func main() {
	fmt.Println("=== 01: Go Runtime, Memory Allocation & Escape Analysis ===")

	heapUser := NewUserHeap("Alice (Heap)")
	fmt.Printf("Heap User: %+v, Address: %p\n", heapUser, heapUser)

	stackUser := NewUserStack("Bob (Stack)")
	fmt.Printf("Stack User: %+v\n", stackUser)

	// Diagnostic command: go build -gcflags="-m -m" main.go
}

