package main

import "fmt"

func SafeOp() (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("recovered: %v", r)
		}
	}()
	panic("something broke!")
}

func main() {
	fmt.Println("=== 07: Control Flow, Defer Stack & Panic/Recover ===")
	defer fmt.Println("Deferred call executed!")
	err := SafeOp()
	fmt.Println("Recovered err:", err)
}

package main

import "fmt"

type Counter struct{ Count int }

func MutatePointer(c *Counter) { c.Count++ }
func MutateValue(c Counter)    { c.Count++ }

func main() {
	fmt.Println("=== 08: Pointers & Semantics ===")
	c := Counter{Count: 0}
	MutateValue(c)
	fmt.Println("After Value  :", c.Count) // 0
	MutatePointer(&c)
	fmt.Println("After Pointer:", c.Count) // 1
}

package main

import "fmt"

type CustomErr struct{}
func (c *CustomErr) Error() string { return "fail" }

func GetErr(ok bool) error {
	var err *CustomErr = nil
	if !ok {
		// Returns typed nil: Interface is NOT nil because Type is non-nil!
		return err
	}
	return nil
}

func main() {
	fmt.Println("=== 09: Interfaces & nil Interface Trap ===")
	err := GetErr(false)
	if err != nil {
		fmt.Printf("⚠️ TRAP: err is NOT nil (type=%T, value=%v)\n", err, err)
	}
}

