package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("not found")

func QueryDB() error {
	return fmt.Errorf("db query: %w", ErrNotFound)
}

func main() {
	fmt.Println("=== 11: Error Wrapping & errors.Is ===")
	err := QueryDB()
	if errors.Is(err, ErrNotFound) {
		fmt.Println("Detected ErrNotFound in chain!")
	}
}

package main

import (
	"fmt"
	"runtime"
	"sync"
)

func main() {
	fmt.Println("=== 12: Concurrency & GMP Model ===")
	fmt.Printf("Logical Processors (P): %d\n", runtime.GOMAXPROCS(0))
	var wg sync.WaitGroup
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			fmt.Printf("Goroutine %d executing\n", id)
		}(i)
	}
	wg.Wait()
}

package main

import (
	"context"
	"fmt"
	"time"
)

func main() {
	fmt.Println("=== 14: Context & Timeouts ===")
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()

	select {
	case <-time.After(100 * time.Millisecond):
		fmt.Println("Finished")
	case <-ctx.Done():
		fmt.Println("Context timed out:", ctx.Err())
	}
}

package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"time"
)

func main() {
	fmt.Println("=== 16: Production HTTP Web Server ===")
	mux := http.NewServeMux()
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
	})
	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 10 * time.Second,
	}
	fmt.Println("Server configured on :8080 with timeouts. Ready!")
	_ = server
}

